// Sonde : execute les vraies fonctions majActions et choisirOnglet d'app.js (extraites du fichier) sur un DOM factice
// reduit aux trois onglets et aux trois panneaux de index.html, puis lit l'etat apres un clic sur "Mes textes".
// Usage : node onglet.js <chemin de app.js>
const fs = require("fs");
const src = fs.readFileSync(process.argv[2], "utf8");
const debut = src.indexOf("function majActions()");
const fin = src.indexOf('$("#onglets").addEventListener("click"');
const code = src.slice(debut, fin);

function el(id, hidden) {
  return {id, hidden, attrs: {}, tabIndex: 0,
    setAttribute(k, v) { this.attrs[k] = String(v); }, focus() { this.enfoque = true; }};
}
const dom = {
  "#o-sync": el("o-sync", false), "#o-semaine": el("o-semaine", false), "#o-textes": el("o-textes", false),
  "#v-sync": el("v-sync", false), "#v-semaine": el("v-semaine", true), "#v-textes": el("v-textes", true),
  "#actions-sync": el("actions-sync", false), "#actions-semaine": el("actions-semaine", true),
};
dom["#o-sync"].attrs["aria-selected"] = "true"; dom["#o-sync"].tabIndex = 0;
dom["#o-semaine"].attrs["aria-selected"] = "false"; dom["#o-semaine"].tabIndex = -1;
dom["#o-textes"].attrs["aria-selected"] = "false"; dom["#o-textes"].tabIndex = -1;
const $ = s => dom[s];
let ONGLET = "sync", INFOS = {semaine_active: true};
const placerCurseur = () => {};
const requestAnimationFrame = f => f();
const f = new Function("$", "INFOS", "placerCurseur", "requestAnimationFrame",
  code + "; return {choisirOnglet, get ONGLET() { return ONGLET; }};".replace("get ONGLET() { return ONGLET; }", "") );
// ONGLET est une variable de module dans app.js : on la reproduit par une portee commune
const g = new Function("$", "INFOS", "placerCurseur", "requestAnimationFrame",
  "let ONGLET = 'sync';\n" + code + "\nreturn {choisirOnglet, lire: () => ONGLET};");
const api = g($, INFOS, placerCurseur, requestAnimationFrame);

function etat(titre) {
  console.log(titre);
  for (const n of ["sync", "semaine", "textes"]) {
    const o = dom["#o-" + n], v = dom["#v-" + n];
    console.log("  %-8s aria-selected=%-5s tabindex=%-2s panneau.hidden=%s", n, o.attrs["aria-selected"], o.tabIndex, v.hidden);
  }
  console.log("  #actions-sync.hidden=%s  #actions-semaine.hidden=%s  ONGLET=%s", dom["#actions-sync"].hidden, dom["#actions-semaine"].hidden, api.lire());
}
api.choisirOnglet("sync"); etat("apres choisirOnglet('sync') :");
api.choisirOnglet("semaine"); etat("apres choisirOnglet('semaine') :");
api.choisirOnglet("textes"); etat("apres choisirOnglet('textes') (clic sur Mes textes) :");

